function Ic({n}){return React.createElement('svg',{viewBox:'0 0 24 24',width:'1em',height:'1em',fill:FILL[n]?'currentColor':'none',stroke:'currentColor',strokeWidth:1.7,strokeLinecap:'round',strokeLinejoin:'round','aria-hidden':true,style:{verticalAlign:'-0.15em',flex:'none',color:COL[n]},dangerouslySetInnerHTML:{__html:ICONS[n]}})}
const tx=c=>typeof c==='string'?(c.split(RX).length>1?c.split(RX).map((x,i)=>MAP[x]?React.createElement(Ic,{n:MAP[x],key:i}):x):c):Array.isArray(c)?c.map(tx):c;
