function SwipeCard({p,onAct,onOpen}){
 const [dx,setDx]=useState(0);const [info,setInfo]=useState(false);const st=useRef(null);const cap=useRef(0);const ptr=useRef(0);
 const down=e=>{st.current=e.clientX;ptr.current=e.pointerId};
 const move=e=>{if(st.current===null)return;const d=e.clientX-st.current;if(Math.abs(d)>6&&!cap.current){cap.current=1;e.currentTarget.setPointerCapture(ptr.current)}setDx(d)};
 const up=()=>{if(st.current===null)return;st.current=null;cap.current=0;if(dx>110)onAct('like');else if(dx<-110)onAct('pass');setDx(0)};
 return html`<div className="sw" style=${{transform:`translateX(${dx}px) rotate(${dx/18}deg)`,transition:st.current===null?'transform .25s':'none'}} onPointerDown=${down} onPointerMove=${move} onPointerUp=${up} onPointerCancel=${up}>
  <div className="hero" style=${{background:p.img?`center 22%/cover url(${p.img})`:`linear-gradient(135deg,${p.c},#fff3)`}}>${p.img?null:p.e}<span className="pill" style=${{display:'flex',gap:6,alignItems:'center'}}><i style=${{width:8,height:8,borderRadius:'50%',background:'#17a34a'}}></i><span>Disponible<br/>en Temuco</span></span>
   ${dx>40&&html`<span className="stamp" style=${{left:16,color:'#17a34a',borderColor:'#17a34a'}}>ME INTERESA</span>`}
   ${dx<-40&&html`<span className="stamp" style=${{right:16,color:'#e11d48',borderColor:'#e11d48'}}>PASAR</span>`}
   <div className="cap"><div className="row"><div className="av" style=${{width:46,height:46,fontSize:18,borderRadius:13}}>${p.name.split(' ').map(w=>w[0]).slice(0,2).join('')}</div>
    <div style=${{flex:1,minWidth:0}}><b style=${{fontSize:19}}>${p.name}</b><div style=${{fontSize:13}}>${p.role} · ⭐ <b>${p.r}</b> (${p.n})</div></div>
    ${p.ver&&html`<span className="ver" style=${{padding:'5px 9px',fontSize:12}}>🛡️ Verificado</span>`}</div></div></div>
  <div className="inf">
   <div className="row" style=${{fontSize:13}}><b style=${{color:'#ff5a00'}}>${p.cat.toUpperCase()}</b><span className="mut">📍 ${p.loc}</span></div>
   <div className="clamp" style=${{fontSize:13,margin:'4px 0 6px'}}>${p.bio}</div>
   <button className="chip" style=${{width:'100%',background:'var(--soft)',borderRadius:12,display:'flex',justifyContent:'space-between',padding:'5px 12px'}} onClick=${()=>setInfo(i=>!i)}><span>ⓘ  Más info</span><span>${info?'▴':'▾'}</span></button>
   ${info&&html`<div className="mut" style=${{marginTop:4,fontSize:12}}>${p.jobs} trabajos · 0 reclamos abiertos · Responde en menos de 1 hora</div>`}
   <div className="acts"><div className="act"><b onClick=${()=>onAct('pass')} style=${{color:'#ff5a00'}}>✕</b>Pasar</div><div className="act"><b onClick=${()=>onAct('save')}>♥</b>Guardar perfil</div><div className="act big"><b onClick=${()=>onAct('like')}>👍</b>Me interesa</div></div>
   <button className="btn" onClick=${onOpen}>Ver portafolio completo ›</button>
  </div></div>`;
}
const AV=[1,2,3,5];
const km=p=>parseFloat(((p.loc.match(/([\d,]+) km/)||[])[1]||'99').replace(',','.'));
const FL0={inm:false,ver:false,dist:0,top:false,cats:[],emp:false};
const okp=(p,fl)=>!p.sus&&(!fl.inm||AV.includes(p.id))&&(!fl.ver||p.ver)&&(!fl.dist||km(p)<=fl.dist)&&(!fl.top||p.r>=4.8)&&(!fl.cats.length||fl.cats.includes(p.cat))&&(!fl.emp||p.role.includes('Empresa'));
function Explore({pros,seen,act,setView,saved,filt,setFilt,fl,setFl}){
 const vis=pros.filter(p=>okp(p,fl));const deck=vis.filter(p=>!seen.includes(p.id));const top=deck[0];
 const tg=k=>setFl(f=>({...f,[k]:!f[k]}));
 const tc=c=>setFl(f=>({...f,cats:f.cats.includes(c)?f.cats.filter(x=>x!==c):[...f.cats,c]}));
 const Opt=(k,ic,l)=>html`<button className=${'chip'+(fl[k]?' on':'')} onClick=${()=>tg(k)}>${ic} ${l}</button>`;
 return html`<div className="ex">
  <div className="chips" style=${{flex:'none'}}><button className=${'chip'+(fl.cats.length?'':' on')} onClick=${()=>setFl(f=>({...f,cats:[]}))}>${ICO.Todos} Todos</button>${CATS.slice(1).map(c=>html`<button key=${c} className=${'chip'+(fl.cats.includes(c)?' on':'')} onClick=${()=>tc(c)}>${ICO[c]} ${c}</button>`)}</div>
  <div className="deck">${top?html`<${SwipeCard} key=${top.id} p=${top} onAct=${t=>act(top,t)} onOpen=${()=>setView({t:'pro',id:top.id})}/>`:html`<div className="card" style=${{textAlign:'center',marginTop:40}}><div style=${{fontSize:60}}>🏁</div><b>${vis.length?'No hay más profesionales por ahora':'Sin resultados con estos filtros'}</b><p className="mut">Cambia los filtros o revisa tus perfiles guardados (${saved.length}).</p><button className="btn sm" onClick=${()=>setFl(FL0)}>Limpiar filtros</button></div>`}</div>
  ${filt&&html`<div className="fp"><div className="row sp"><b style=${{fontSize:18}}>Filtros</b><button className="chip" onClick=${()=>setFl(FL0)}>Limpiar</button></div><div className="mut">Puedes elegir varias opciones a la vez</div>
   <h4>Disponibilidad y confianza</h4><div className="wrap">${Opt('inm','⚡','Disponibilidad inmediata')}${Opt('ver','🛡️','Profesionales verificados')}${Opt('top','⭐','Mejor calificados')}${Opt('emp','🏢','Solo empresas')}</div>
   <h4>Distancia</h4><div className="wrap">${[3,5,10].map(d=>html`<button key=${d} className=${'chip'+(fl.dist===d?' on':'')} onClick=${()=>setFl(f=>({...f,dist:f.dist===d?0:d}))}>📍 Hasta ${d} km</button>`)}</div>
   <h4>Especialidades</h4><div className="wrap">${CATS.slice(1).map(c=>html`<button key=${c} className=${'chip'+(fl.cats.includes(c)?' on':'')} onClick=${()=>tc(c)}>${ICO[c]} ${c}</button>`)}</div>
   <button className="btn" style=${{marginTop:16}} onClick=${()=>setFilt(false)}>Ver ${deck.length} resultado${deck.length===1?'':'s'}</button></div>`}
 </div>`;
}
function Overlay({title,onBack,children,right}){return html`<div className="ov"><div className="hd"><button className="chip" onClick=${onBack}>←</button><span className="logo">MATCHTER<small>${title}</small></span><span style=${{width:40}}>${right}</span></div><div className="main">${children}</div></div>`}

