function Security({disputes,setDisputes,toast}){
 const d=disputes[0];
 if(!d)return html`<div><h2>Reclamos</h2><div className="card"><b>🛡️ Sin disputas activas</b><p className="mut">Todos tus proyectos están en regla. Si hay un problema, repórtalo desde el contrato.</p></div></div>`;
 const upd=f=>setDisputes(ds=>ds.map(x=>x.id===d.id?f(x):x));
 const CH=['Describir el inconveniente de manera objetiva','Aportar evidencias de la obra o pagos','Participar en la llamada de mediación','Revisar y firmar la propuesta de acuerdo final'];
 return html`<div><h2>Resolución de Problemas</h2>
  <div className="card"><div className="row sp"><b>Caso #${d.id} - ${d.title}</b><span className=${'tag '+(d.step>=3?'g':'')}>${d.step>=3?'RESUELTO':'DISPUTA ACTIVA'}</span></div><div className="mut">from ${d.from} (en proyecto)</div>
   <div className="step">${PSTEPS.map((s,i)=>html`<div key=${i} style=${{textAlign:'center',flex:1,fontSize:11}}><div className=${'dot '+(i<d.step?'c':i===d.step?'d':'')} style=${{margin:'0 auto 4px'}}>${i<d.step?'✓':i+1}</div>${i+1}. ${s}</div>`)}</div></div>
  <h3>1. Canales de apoyo y mediación</h3>
  <div className="row" style=${{alignItems:'stretch'}}><div className="card" style=${{flex:1,background:'#e3f8ea'}}><b style=${{fontSize:13}}>💬 Chat con mediador</b><button className="btn gr sm" style=${{marginTop:8}} onClick=${()=>toast('Un mediador te atenderá en breve')}>Iniciar chat</button></div><div className="card" style=${{flex:1}}><b style=${{fontSize:13}}>📅 Llamada programada</b><div className="mut">Lunes 23 de Nov, 15:00 hrs</div><button className="btn sm" style=${{marginTop:6}} onClick=${()=>{upd(x=>({...x,conf:true}));toast('Asistencia confirmada')}}>${d.conf?'✔ Confirmada':'Confirmar'}</button></div></div>
  <h3>2. Carga de evidencias</h3>
  <div className="card" style=${{border:'1.5px dashed #2563eb',textAlign:'center'}}><div style=${{fontSize:30}}>⬆️</div><div className="mut">Fotos, contratos, conversaciones</div><button className="btn sm" style=${{marginTop:8}} onClick=${()=>upd(x=>({...x,files:[...x.files,'Evidencia_'+(x.files.length+1)+'.jpg']}))}>Seleccionar archivos</button></div>
  ${d.files.map((f,i)=>html`<div key=${f+i} className="card row sp" style=${{padding:10,marginBottom:8}}><span>📎 ${f} <span className="mut">· ● subido</span></span><button className="chip" onClick=${()=>upd(x=>({...x,files:x.files.filter((_,k)=>k!==i)}))}>🗑</button></div>`)}
  <h3>3. Pasos para la resolución</h3>
  ${CH.map((c,i)=>html`<label key=${i} className="row" style=${{margin:'8px 0',fontSize:14}}><input type="checkbox" checked=${!!d.checks[i]} onChange=${()=>upd(x=>({...x,checks:x.checks.map((v,k)=>k===i?!v:v)}))}/> ${i+1}. ${c}</label>`)}
  <div className="card" style=${{background:'#dbe8ff',color:'#1e3a8a'}}>ⓘ La mediación es imparcial y busca un acuerdo justo para ambas partes.</div></div>`;
}

/* ---------- Admin ---------- */
function Admin({pros,setPros,jobs,disputes,setDisputes,pays,setPays,tab,setTab,exit}){
 const T=[['res','📊','Resumen'],['usr','👷','Usuarios'],['rec','⚖️','Reclamos'],['pag','💳','Pagos']];
 const cust=pays.filter(p=>p.s==='En custodia').reduce((a,p)=>a+p.a,0);
 const W=[12,18,15,24,30,22,35];
 return html`<div className="app"><div className="hd"><span className="logo">MATCHTER<small>Admin</small></span><button className="chip" onClick=${exit}>Salir ↩</button></div>
 <div className="main">${tab==='res'&&html`<div><h2>Panel de administración</h2>
   <div className="kpi">${[['Profesionales',pros.length],['Verificados',pros.filter(p=>p.ver).length],['Matches (total)',120+jobs.length],['Disputas activas',disputes.filter(d=>d.step<3).length],['En custodia',fmt(cust)],['Calif. promedio','4.8']].map(([l,v])=>html`<div key=${l} className="card"><span className="mut">${l}</span><b style=${{fontSize:String(v).length>6?16:24}}>${v}</b></div>`)}</div>
   <div className="card" style=${{marginTop:12}}><b>Matches por semana</b><div className="row" style=${{alignItems:'flex-end',height:110,marginTop:10}}>${W.map((v,i)=>html`<div key=${i} style=${{flex:1,textAlign:'center',fontSize:10}}>${v}<div style=${{height:v*2.4,background:'#ff5a00',borderRadius:5}}></div>S${i+1}</div>`)}</div></div></div>`}
  ${tab==='usr'&&html`<div><h2>Usuarios y profesionales</h2>${pros.map(p=>html`<div key=${p.id} className="card"><div className="row"><div className="av">${p.e}</div><div style=${{flex:1}}><b>${p.name}</b><div className="mut">${p.role} · ⭐ ${p.r}</div></div>${p.sus?html`<span className="tag r">Suspendido</span>`:p.ver?html`<span className="tag g">Verificado</span>`:html`<span className="tag">Pendiente</span>`}</div>
   <div className="row" style=${{marginTop:10}}><button className="btn sm" onClick=${()=>setPros(ps=>ps.map(x=>x.id===p.id?{...x,ver:!x.ver}:x))}>${p.ver?'Quitar verificación':'Verificar'}</button><button className=${'btn sm '+(p.sus?'gr':'dk')} onClick=${()=>setPros(ps=>ps.map(x=>x.id===p.id?{...x,sus:!x.sus}:x))}>${p.sus?'Reactivar':'Suspender'}</button></div></div>`)}</div>`}
  ${tab==='rec'&&html`<div><h2>Reclamos y mediación</h2>${disputes.length===0&&html`<p className="mut">Sin reclamos.</p>`}${disputes.map(d=>html`<div key=${d.id} className="card"><div className="row sp"><b>#${d.id} ${d.title}</b><span className=${'tag '+(d.step>=3?'g':'')}>${d.step>=3?'Resuelto':PSTEPS[d.step]}</span></div><div className="mut">Profesional: ${d.from} · ${d.files.length} evidencias</div>
   <div className="row" style=${{marginTop:10}}><button className="btn sm" disabled=${d.step>=3} onClick=${()=>setDisputes(ds=>ds.map(x=>x.id===d.id?{...x,step:x.step+1}:x))}>Avanzar etapa</button><button className="btn sm out" disabled=${d.step>=3} onClick=${()=>setDisputes(ds=>ds.map(x=>x.id===d.id?{...x,step:3}:x))}>Cerrar caso</button></div></div>`)}</div>`}
  ${tab==='pag'&&html`<div><h2>Pagos en custodia</h2><div className="card"><table><thead><tr><th>ID</th><th>Proyecto</th><th>Monto</th><th></th></tr></thead><tbody>${pays.map(p=>html`<tr key=${p.id}><td>${p.id}</td><td>${p.p}<div className=${'tag '+(p.s==='Liberado'?'g':p.s==='Retenido'?'r':'')}>${p.s}</div></td><td>${fmt(p.a)}</td><td>${p.s==='En custodia'&&html`<div className="row"><button className="chip" onClick=${()=>setPays(ps=>ps.map(x=>x.id===p.id?{...x,s:'Liberado'}:x))}>Liberar</button><button className="chip" onClick=${()=>setPays(ps=>ps.map(x=>x.id===p.id?{...x,s:'Retenido'}:x))}>Retener</button></div>`}</td></tr>`)}</tbody></table></div></div>`}
 </div><div className="nav">${T.map(([k,i,l])=>html`<button key=${k} className=${tab===k?'on':''} onClick=${()=>setTab(k)}><span>${i}</span>${l}</button>`)}</div></div>`;
}

